from capture import *
with scene('22-people-access','02-manager-role','Assign a role, then save the account','Choose only the role the person needs. Manager access supports reviewing requests, deciding approvals, and handling shortfalls. Account status is separate from role membership. The Active option controls whether the person can sign in. This is a demo password; in a real installation, use your organisation’s account and password procedures.', 'Mira Shah'):
 fill('Email','mira@demo.fervid.local');check('checkbox','Manager — Review and decide on payment requests.');fill('Password','DemoPass2026!');click('button','Add User')
with scene('22-people-access','03-accounts-role','Separate payment processing from approval','Next, create Anil in Accounts. This person will claim approved work, record payment details, and manage recovery entries where permitted. Creating a user does not send a payment or create an accounting entry. The role controls available actions; the scope configured for that role controls which records those actions can reach.', 'Anil Rao'):
 click('button','＋ Add user');fill('Email','anil@demo.fervid.local');fill('Name','Anil Rao');check('checkbox','Accounts — Process approved requests and record payments.');fill('Password','DemoPass2026!');click('button','Add User')
with scene('22-people-access','04-requester-role','Give requesters their own identity','Riya will raise and track her own requests. Keeping separate accounts makes the requester, manager, and payment recorder visible in history. Avoid sharing one account across the team: shared credentials make it harder to establish who made a decision. We will use Riya’s account for the submission workflows in this course.', 'Riya Menon'):
 click('button','＋ Add user');fill('Email','riya@demo.fervid.local');fill('Name','Riya Menon');check('checkbox','Requester — Raise and manage your own payment requests.');fill('Password','DemoPass2026!');click('button','Add User')
snapshot('foundation-users-created')
